  // Touched by Magic (Mala, 2026-10-10). A BIOLOGY trait, `touchedByMagic` in insight/insight-data.js: innate, never
  // imitable. This is the roster of who carries it, confirmed by Mala. An entity that already has an Insight deck
  // carries the trait there too (tests/performers.test.mjs fails if the two ever disagree); the ones listed under
  // `awaitingDeck` have no deck yet and must be given the trait when theirs is authored.
  // The soothe tables in kits-data.js read these listener kinds:
  //   touchedCharacter    a person touched by magic: resists a charm like any other song
  //   untouchedCharacter  everyone else: no practice against magic, so a charm takes more often
  //   touchedCreature     a non-character entity touched by magic; dream monsters are "dream", wild creatures "wild"
  const magic = {
    trait: "touchedByMagic",
    classes: ["wizard", "jujutsu_sorcerer", "pharaoh", "bastet", "medusa", "cleric", "paladin", "bard"],
    creatures: ["dragon", "oni", "gaia"],   // boss ids (bosses/boss-data.js): Dragon, Yokai (oni), Gaia; the Insect Kaiju is a beast
    awaitingDeck: ["medusa", "paladin", "oni"],   // the Dragon got its deck with the boss keys (2026-10-18)
    note: "Technology, mutation, training and super powers are not magic: Teleporter, Gemini, the Supers, Mutant Boar, Clockwork and every roster character are untouched.",
    // A unit's own traits win (so one individual can be touched without its whole class being); the roster covers
    // entities whose traits haven't been drawn or authored.
    isTouched(unit = {}) {
      const traits = (unit.traits || []).map((t) => (typeof t === "string" ? t : t.id));
      if (traits.includes(magic.trait)) return true;
      const id = String(unit.classId || unit.character || unit.boss || unit.kind || "").replace(/-/g, "_");
      return magic.classes.includes(id) || magic.creatures.includes(id);
    },
    listenerKind(unit = {}) {
      if (unit.dream) return "dream";
      const creature = !!(unit.wild || unit.side === "wild" || unit.boss);
      if (magic.isTouched(unit)) return creature ? "touchedCreature" : "touchedCharacter";
      return creature ? "wild" : "untouchedCharacter";
    },
  };

