    // Timing is a new pair.
    jatayu: C("jatayu", "Jatayu", ["Interposition", "Timing"], ["Interposition", "Timing", "Reciprocal Obligation"],
      [["late_by_design", "He opens circling high above (no acts his first turn), then comes down hard: x1.3 dealt for 2 rounds. A blow brings him down at once."],
       ["last_word", "When he falls, whoever killed him is marked for his side: x1.25 taken for 3 rounds."]],
      { primaryBasic: "Shield of Wings: the next hit on an adjacent ally lands on him (Sita: the next two, over two turns).", primaryRefined: "Keen Sight: reveal one hidden observation of a foe within 6.", secondaryBasic: "Talon Dive: 10 nigredo to the first foe in a line within 4.", secondaryRefined: "Recovery Cut: 12 piercing to an adjacent foe, x1.3 in their recovery window." },
      "Against the Chariot: announce it; 16 nigredo to the first foe in a line within 6, 24 against Ravana.",
      { strength: "He arrives hard after a turn of circling, shields one ally, and his death marks his killer for everyone else.", weakness: "His first turn is empty and his body is old: strike him before he stoops, or with someone you can afford to have marked." },
      { weakTo: "Early ranged blows (they bring him down before the stoop matters); a killer his side cannot reach.", strongAgainst: "Ravana (Against the Chariot), foes who dive the ally under his wings.", strongWith: "Sita (his wings hold twice), Rama (his mark points the way).", bypass: "None.", negate: "None.", neutral: "A foe who never strikes him: his last word never speaks." },
      { origin: "Ramayana (Valmiki, Aranya Kanda); Mala 2026-10-24: the Mythic Vulture Warrior sheet", art: "jatayu", status: "playable",
        existingAbilities: { secondaryRefined: "recoveryCut" },
        kit: ["shieldOfWings", "keenSight", "talonDive", "recoveryCut", "againstTheChariot"], rules: "content.js states (State Kit), classes/class-runtime.js guard thematic + namedStrike" }),
    // Surpanakha (Mala, 2026-10-24; docs/surpanakha-build.md): crew lanka, Ravana's sister. Glamour + Plasticity is a new pair.
